@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-grid {
    --_nz-grid-gap: var(--nz-grid-gutter);

    display: grid;
    grid-template-columns: repeat(var(--nz-grid-columns), minmax(0, 1fr));
    gap: var(--_nz-grid-gap);
  }

  .nz-grid[data-gap='0'] {
    --_nz-grid-gap: var(--nz-space-0);
  }

  .nz-grid[data-gap='0-5'] {
    --_nz-grid-gap: var(--nz-space-0-5);
  }

